       (ins) => ins.status == 'convocada' && ins.convocadaAte != null,
     );
     if (!hasConvocada) return;
     _clock = DateTime.now();
     _countdown = Timer.periodic(const Duration(seconds: 1), (_) {
       if (!mounted) return;
       setState(() => _clock = _clock.add(const Duration(seconds: 1)));
     });
   }

   String get _emptyMessage =>
